<script setup lang="ts">
import { ref, watch } from 'vue';
import { api, state, currentProject, loadCollections, notify, errorMessage } from '../lib/store';
import { buildSchema, fieldTypes, type Field } from '../lib/schema';
import type { Collection } from '@kestrel/client';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
const open = ref(false); const name = ref(''); const fields = ref<Field[]>([{ name: 'title', type: 'string', required: true }]);
const busy = ref(false); const error = ref(''); const selected = ref<Collection | null>(null); const deleting = ref<Collection | null>(null); const confirmation = ref('');
watch(() => state.projectId, () => { selected.value = null; });
async function create() {
  busy.value = true; error.value = '';
  try { const schema = buildSchema(fields.value); await api.value.createCollection(state.projectId, { name: name.value, schema }); await loadCollections(); open.value = false; name.value = ''; fields.value = [{ name: 'title', type: 'string', required: true }]; notify('Collection created with your schema.'); }
  catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
async function remove() {
  if (!deleting.value || confirmation.value !== deleting.value.name) return;
  busy.value = true; error.value = '';
  try { await api.value.deleteCollection(state.projectId, deleting.value.name); await loadCollections(); deleting.value = null; selected.value = null; confirmation.value = ''; notify('Collection and its records deleted.'); }
  catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">GIVE YOUR DATA SOME STRUCTURE</div><h1>Collections<span class="heading-dot">.</span></h1><p>Typed schemas for <strong>{{ currentProject?.name ?? 'your project' }}</strong>. A little structure goes a long way.</p></div><button class="button primary" :disabled="!currentProject?.api_enabled" @click="open = true"><Icon name="plus" :size="17" />New collection</button></div>
  <div v-if="!currentProject" class="panel empty-state"><Icon name="folder" :size="36" /><h2>Start with a project</h2><p>Collections live inside a project. Create one to give your data a home.</p><RouterLink to="/projects" class="button primary">Create a project</RouterLink></div>
  <div v-else-if="!currentProject.api_enabled" class="panel empty-state"><Icon name="shield" :size="36" /><h2>The data API is paused</h2><p>Enable it in project settings to browse or change collections.</p><RouterLink to="/settings" class="button secondary">Open settings</RouterLink></div>
  <template v-else>
    <div class="collection-layout">
      <section class="panel collection-list"><div class="panel-heading"><h2>Your collections</h2><span class="count-badge">{{ state.collections.length }}</span></div><div v-if="!state.collections.length" class="empty-small">No collections yet.<br>Create your first schema.</div><button v-for="collection in state.collections" :key="collection.id" :class="['collection-item', { active: selected?.id === collection.id }]" @click="selected = collection"><Icon name="table" :size="19" /><span><strong>{{ collection.name }}</strong><small>{{ Object.keys(collection.schema.properties).length }} fields</small></span><Icon name="arrow" :size="15" /></button></section>
      <section class="panel schema-panel"><template v-if="selected"><div class="panel-heading"><div><span class="eyebrow">COLLECTION SCHEMA</span><h2>{{ selected.name }}</h2></div><button class="icon-button danger-text" aria-label="Delete collection" @click="deleting = selected; confirmation = ''; error = ''"><Icon name="trash" :size="18" /></button></div><div class="schema-table"><div class="schema-row schema-head"><span>Field name</span><span>Type</span><span>Required</span></div><div v-for="(field, fieldName) in selected.schema.properties" :key="fieldName" class="schema-row"><code>{{ fieldName }}</code><span class="type-badge">{{ field.type }}</span><span>{{ selected.schema.required.includes(String(fieldName)) ? 'Yes' : 'No' }}</span></div><div v-if="!Object.keys(selected.schema.properties).length" class="empty-small">This collection accepts empty objects.</div></div><div class="schema-footer"><span><Icon name="shield" :size="15" />Unknown fields are rejected</span><RouterLink :to="`/records?collection=${encodeURIComponent(selected.name)}`" class="text-link">Explore records <Icon name="arrow" :size="15" /></RouterLink></div><details class="json-details"><summary>View JSON Schema</summary><pre>{{ JSON.stringify(selected.schema, null, 2) }}</pre></details></template><div v-else class="empty-state"><span class="empty-icon"><Icon name="database" :size="32" /></span><h2>A place for every field</h2><p>Select a collection to inspect its schema,<br>or create a new one to get started.</p><button class="button secondary" @click="open = true"><Icon name="plus" :size="16" />Create collection</button></div></section>
    </div>
    <div class="info-strip"><Icon name="code" :size="20" /><div><strong>Your schema is your contract.</strong><span> Records are validated on write. Supported types: string, integer, number, boolean, object, array, and null.</span></div></div>
  </template>
  <Modal v-if="open" title="Create a collection" wide @close="open = false"><p class="muted">Name your collection and define the fields it should contain.</p><form @submit.prevent="create"><label>Collection name<input v-model="name" required maxlength="63" pattern="[a-z][a-z0-9_]*" placeholder="products" /><span class="field-hint">Lowercase letters, numbers, and underscores.</span></label><div class="field-builder"><div class="builder-head"><span>Field name</span><span>Type</span><span>Required</span><span></span></div><div v-for="(field, index) in fields" :key="index" class="builder-row"><input v-model="field.name" :aria-label="`Field ${index + 1} name`" required maxlength="63" placeholder="field_name" /><select v-model="field.type" :aria-label="`Field ${index + 1} type`"><option v-for="type in fieldTypes" :key="type">{{ type }}</option></select><input v-model="field.required" type="checkbox" :aria-label="`Field ${index + 1} required`" /><button type="button" class="icon-button" aria-label="Remove field" :disabled="fields.length === 1" @click="fields.splice(index, 1)"><Icon name="close" :size="16" /></button></div></div><button type="button" class="text-button add-field" :disabled="fields.length >= 32" @click="fields.push({ name: '', type: 'string', required: false })"><Icon name="plus" :size="16" />Add field</button><p v-if="error" class="error-box" role="alert">{{ error }}</p><div class="modal-actions"><button type="button" class="button secondary" @click="open = false">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Creating…' : 'Create collection' }}</button></div></form></Modal>
  <Modal v-if="deleting" title="Delete collection?" @close="deleting = null"><p>This permanently deletes <strong>{{ deleting.name }}</strong> and all its records in this project. This cannot be undone.</p><form @submit.prevent="remove"><label>Type the collection name to confirm<input v-model="confirmation" :placeholder="deleting.name" autocomplete="off" /></label><p v-if="error" class="error-box" role="alert">{{ error }}</p><div class="modal-actions"><button type="button" class="button secondary" @click="deleting = null">Keep collection</button><button class="button danger" :disabled="busy || confirmation !== deleting.name">Delete collection</button></div></form></Modal>
</template>
